/**
 * Types for a paginated blog post list API response.
 *
 * @phpstan-type PostSummary array{
 *   id: positive-int,
 *   slug: non-empty-string,
 *   title: string
 * }
 * @phpstan-type PaginationMeta array{
 *   page: positive-int,
 *   perPage: positive-int,
 *   total: int
 * }
 * @phpstan-type PostListResponse array{
 *   posts: list<PostSummary>,
 *   meta: PaginationMeta
 * }
 */

expected:
/**
 * @phpstan-type PostSummary array{ id: positive-int, slug: non-empty-string, title: string }
 * @phpstan-type PaginationMeta array{ page: positive-int, perPage: positive-int, total: int }
 * @phpstan-type PostListResponse array{ posts: list<PostSummary>, meta: PaginationMeta }
 */

/** @phpstan-assert-if-true PostSummary $value */
function isPostSummary(mixed $value): bool
{
    return (is_array($value) && array_key_exists('id', $value) && array_key_exists('slug', $value) && array_key_exists('title', $value) && is_int($value['id']) && $value['id'] > 0 && is_string($value['slug']) && $value['slug'] !== '' && is_string($value['title']));
}


/** @phpstan-assert-if-true PaginationMeta $value */
function isPaginationMeta(mixed $value): bool
{
    return (is_array($value) && array_key_exists('page', $value) && array_key_exists('perPage', $value) && array_key_exists('total', $value) && is_int($value['page']) && $value['page'] > 0 && is_int($value['perPage']) && $value['perPage'] > 0 && is_int($value['total']));
}


/** @phpstan-assert-if-true PostListResponse $value */
function isPostListResponse(mixed $value): bool
{
    if (
        !is_array($value) ||
        !array_key_exists('posts', $value) ||
        !is_array($value['posts']) ||
        !array_is_list($value['posts'])
    ) {
        return FALSE;
    }
    foreach ($value['posts'] as $var0) {
        if (!isPostSummary($var0)) {
            return FALSE;
        }
    }
    return (array_key_exists('meta', $value) && isPaginationMeta($value['meta']));
}
